import { useState, useMemo } from 'react'
import UnitInput from '../../components/shared/UnitInput'
import FySelect from '../../components/shared/FySelect'
import ResultBox from '../../components/shared/ResultBox'
import RebarSpacingList from '../../components/shared/RebarSpacingList'
import { calcSlabReinf } from '../../engines/slabReinf'

const REBAR_METRIC   = [
  { name: 'D10', area_mm2: 71.3  }, { name: 'D13', area_mm2: 126.7 },
  { name: 'D16', area_mm2: 198.6 }, { name: 'D19', area_mm2: 284.9 },
  { name: 'D22', area_mm2: 387.1 }, { name: 'D25', area_mm2: 506.7 },
]
const REBAR_IMPERIAL = [
  { name: '#3', area_in2: 0.11 }, { name: '#4', area_in2: 0.20 },
  { name: '#5', area_in2: 0.31 }, { name: '#6', area_in2: 0.44 },
  { name: '#7', area_in2: 0.60 }, { name: '#8', area_in2: 0.79 },
]
const MM_TO_IN = 0.03937

export default function SlabView() {
  const [h_mm,   setH]  = useState('200')
  const [fy_mpa, setFy] = useState(400)
  const [layer,  setLayer] = useState('single')   // 'single' | 'double'

  const result = useMemo(() => {
    const h = parseFloat(h_mm) || 0
    return calcSlabReinf({ h_mm: h, fy_mpa, rebarMetric: REBAR_METRIC, rebarImperial: REBAR_IMPERIAL })
  }, [h_mm, fy_mpa])

  // For double: each face = As_min/2, so spacing doubles
  const layerFactor = layer === 'double' ? 2 : 1

  return (
    <div>
      <h3 style={titleStyle}>SLAB &amp; FOUNDATION — Min. Shrinkage &amp; Temperature Reinforcement</h3>
      <p style={descStyle}>KDS 14 20 50 §4.6.2 / ACI 318-19 Table 24.4.3.2</p>

      {/* Single / Double toggle */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 20, alignItems: 'center' }}>
        {[{ id: 'single', label: 'SINGLE' }, { id: 'double', label: 'DOUBLE' }].map(opt => (
          <button key={opt.id} onClick={() => setLayer(opt.id)} style={{
            padding: '6px 18px', borderRadius: 6, fontSize: 12, fontWeight: 600, cursor: 'pointer',
            border: '1px solid var(--bd-subtle)',
            background: layer === opt.id ? 'var(--ac-main)' : 'var(--bg-card)',
            color: layer === opt.id ? '#000' : 'var(--tx-secondary)',
          }}>{opt.label}</button>
        ))}
        {layer === 'double' && (
          <span style={{ fontSize: 11, color: 'var(--tx-muted)' }}>
            Each face = As,min / 2 → spacing × 2
          </span>
        )}
      </div>

      <div className="grid md:grid-cols-2 gap-8">
        {/* KS Metric */}
        <div style={cardKS}>
          <h4 style={cardTitle('ks')}>🇰🇷 KS CODE (METRIC)</h4>
          <UnitInput id="slab-h-mm" label="Slab Thickness h" unit="mm"
            value={h_mm} onChange={v => setH(v)} />
          <div style={{ marginBottom: 16 }}>
            <label style={labelStyle}>Steel Yield Strength fy</label>
            <FySelect fy_mpa={fy_mpa} onChange={setFy} />
          </div>
          {result && (
            <ResultBox title={`Min. Reinforcement As,min — ${layer === 'double' ? 'DOUBLE (per face)' : 'SINGLE'} (KDS)`} accent>
              <Row label="ρ_min"   value={result.metric.rho_min.toFixed(4)} />
              <Row label={layer === 'double' ? 'As,min / face' : 'As,min'}
                   value={`${(result.metric.As_min / layerFactor).toFixed(0)} mm²/m`} highlight />
              {layer === 'double' && (
                <Row label="Total As,min" value={`${result.metric.As_min.toFixed(0)} mm²/m (both faces)`} />
              )}
              <Divider label="D-Bar Spacing (mm)" />
              <RebarSpacingList
                items={result.metric.spacing.map(s => ({
                  name: s.name,
                  spacing: s.spacing_mm * layerFactor,
                }))}
                unit="mm"
              />
            </ResultBox>
          )}
        </div>

        {/* ACI Imperial */}
        <div style={cardACI}>
          <h4 style={cardTitle('aci')}>🇺🇸 ACI CODE (IMPERIAL)</h4>
          <UnitInput id="slab-h-in" label="Slab Thickness h" unit="in"
            value={h_mm ? ((parseFloat(h_mm) || 0) * MM_TO_IN).toFixed(2) : ''}
            onChange={v => setH(((parseFloat(v) || 0) / MM_TO_IN).toFixed(1))} />
          <div style={{ marginBottom: 16 }}>
            <label style={labelStyle}>Steel Yield Strength fy</label>
            <FySelect fy_mpa={fy_mpa} onChange={setFy} />
          </div>
          {result && (
            <ResultBox title={`Required Min. Steel — ${layer === 'double' ? 'DOUBLE (per face)' : 'SINGLE'} (ACI)`}>
              <Row label="ρ_min"   value={result.imperial.rho_min.toFixed(4)} />
              <Row label={layer === 'double' ? 'As,min / face' : 'As,min'}
                   value={`${(result.imperial.As_min / layerFactor).toFixed(3)} in²/ft`} highlight />
              {layer === 'double' && (
                <Row label="Total As,min" value={`${result.imperial.As_min.toFixed(3)} in²/ft (both faces)`} />
              )}
              <Divider label="Bar Spacing (in)" />
              <RebarSpacingList
                items={result.imperial.spacing.map(s => ({
                  name: s.name,
                  spacing: s.spacing_in * layerFactor,
                }))}
                unit="in"
              />
            </ResultBox>
          )}
        </div>
      </div>
    </div>
  )
}

function Row({ label, value, highlight }) {
  return (
    <p style={{ fontSize: 15, color: 'var(--tx-primary)', marginBottom: 4 }}>
      {label} ={' '}
      <span style={{ fontWeight: 700, color: highlight ? 'var(--val-pos)' : 'var(--ac-main)' }}>
        {value}
      </span>
    </p>
  )
}
function Divider({ label }) {
  return (
    <h5 style={{ fontSize: 11, fontWeight: 600, color: 'var(--tx-secondary)', marginTop: 12, marginBottom: 6, paddingTop: 10, borderTop: '1px solid var(--bd-subtle)' }}>
      {label}
    </h5>
  )
}

const titleStyle = { fontSize: '1.3rem', fontWeight: 700, marginBottom: 8, color: 'var(--tx-primary)', paddingBottom: 10, borderBottom: '1px solid var(--bd-subtle)' }
const descStyle  = { marginBottom: 20, color: 'var(--tx-secondary)', fontSize: 13 }
const labelStyle = { display: 'block', fontSize: 12, fontWeight: 500, color: 'var(--tx-secondary)', marginBottom: 4 }
const cardBase = { background: 'var(--bg-card)', border: '1px solid', borderRadius: 10, padding: 20, transition: 'background 0.25s' }
const cardKS  = { ...cardBase, borderColor: 'var(--bd-accent)' }
const cardACI = { ...cardBase, borderColor: 'var(--bd-muted)' }
function cardTitle(type) {
  return { fontSize: 14, fontWeight: 700, marginBottom: 14, letterSpacing: '0.04em', color: type === 'ks' ? 'var(--ac-main)' : 'var(--tx-primary)' }
}
