/**
 * Slab / Foundation 최소 수축·온도 철근
 * KDS 14 20 50 : 4.6.2  (metric)
 * ACI 318-19   Table 24.4.3.2  (imperial)
 */

const MM_TO_IN = 0.03937;
const MPA_TO_KSI = 0.145038;

/**
 * @param {object} p
 * @param {number} p.h_mm       슬래브 두께 (mm)
 * @param {number} p.fy_mpa     항복강도 (MPa)
 * @param {number} p.fy_ksi     항복강도 (ksi) — 없으면 자동 변환
 * @param {Array}  p.rebarMetric  [{ name, area_mm2 }]
 * @param {Array}  p.rebarImperial [{ name, area_in2 }]
 * @returns {{ metric, imperial }}
 */
export function calcSlabReinf({ h_mm, fy_mpa, fy_ksi, rebarMetric, rebarImperial }) {
  if (h_mm <= 0 || fy_mpa <= 0) return null;

  // ── KDS 14 20 50 : 4.6.2 ──
  const rho_min_ks = fy_mpa <= 400
    ? 0.0020
    : Math.max((0.0020 * 400) / fy_mpa, 0.0014);
  const As_min_ks = rho_min_ks * 1000 * h_mm; // mm²/m

  // ── ACI 318-19 Table 24.4.3.2 ──
  const Fy_ksi = fy_ksi ?? fy_mpa * MPA_TO_KSI;
  const rho_min_aci = Math.max((0.0018 * 60) / Fy_ksi, 0.0014);
  const h_in = h_mm * MM_TO_IN;
  const As_min_aci = rho_min_aci * 12 * h_in; // in²/ft

  return {
    metric: {
      rho_min: rho_min_ks,
      As_min: As_min_ks,
      spacing: rebarMetric.map(bar => ({
        name: bar.name,
        spacing_mm: (bar.area_mm2 * 1000) / As_min_ks,
      })),
    },
    imperial: {
      rho_min: rho_min_aci,
      As_min: As_min_aci,
      spacing: rebarImperial.map(bar => ({
        name: bar.name,
        spacing_in: (bar.area_in2 * 12) / As_min_aci,
      })),
    },
  };
}
